input.sparql:
SELECT ?point ?label ?class WHERE {
  ?point a brick:Space ;
         rdfs:label ?label ;
         brick:hasSubclass* ?cls .
  FILTER(?label IN ("Perimeter_mid_ZN_3", "DataCenter_top_ZN_6"))
  ?point brick:hasPoint* ?sensor .
  ?sensor a ?class .
  FILTER(rdfs:subClassOf*(?class, brick:OccupancySensor))
}

SELECT ?point ?label WHERE {
  ?point a brick:Space ;
         rdfs:label ?label .
  FILTER(?label IN ("Perimeter_mid_ZN_3", "DataCenter_top_ZN_6"))
}

SELECT ?p ?label ?cls WHERE {
  ?p rdfs:label ?label .
  FILTER(CONTAINS(?label, "ZN_3") || CONTAINS(?label, "ZN_6"))
  ?p a ?cls .
} LIMIT 100

SELECT ?point ?tsid WHERE {
  VALUES ?zone { <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02> <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z09> }
  ?zone brick:hasPoint ?point .
  ?point a brick:OccupancySensor .
  ?point ref:hasTimeseriesId ?tsid .
}

SELECT ?point ?cls ?tsid WHERE {
  VALUES ?zone { <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02> <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z09> }
  ?zone brick:hasPoint ?point .
  ?point a ?cls .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
}
